1	import { z } from 'zod';
2	import { completeJson } from '@dailies/agent';
3	import { computeFacts, EvidenceRef, Storyboard, type Beat, type Claim, type Entry, type Facts, type IngestArtifact, type Line, type Scene, type Session } from '@dailies/core';
4	import { collectRuns, type ToolRun } from '@dailies/verify';
5	import { writerPrompt, type WriterMaterial } from '../prompts/writer';
6	import type { Stage } from '../types';
7	import { cut, knownCommits, patchCounts, repoLabel, resolveCommit, type EditArtifact } from './edit';
8	import type { StageDeps } from './index';
9	import type { VerifyArtifact } from './verify';
10	
11	export interface ScriptArtifact { storyboard: Storyboard; discarded: string[] }
12	
13	type SceneOf<T extends Scene['type']> = Extract<Scene, { type: T }>;
14	type Step = SceneOf<'terminal'>['steps'][number];
15	type FlaggedClaim = Claim & { verdict: 'contradicted' | 'stale' };
16	
17	const TARGET_SEC = 75;
18	const MAX_FLAGS = 3;
19	const SPOKEN_QUOTE_CHARS = 120;
20	// What the scene schema allows on screen.
21	const ON_SCREEN = { promptQuote: 280, command: 200, output: 600, hunk: 2400, steps: 4, statValue: 16, flagQuote: 240, flagReality: 200 };
22	// What the writer is shown of each beat.
23	const MATERIAL = { entries: 24, entriesFromStart: 8, entryChars: 400, patches: 3, patchChars: 1500, claims: 12, quoteChars: 200, feedbackChars: 2000 };
24	
25	const STATS: [key: string, label: string][] = [
26	  ['sessions.count', 'Sessions'],
27	  ['commits.count', 'Commits'],
28	  ['files.count', 'Files touched'],
29	  ['turns.total', 'Turns'],
30	  ['tools.calls', 'Tool calls'],
31	  ['duration.minutes', 'Minutes'],
32	];
33	
34	const flat = (text: string) => text.replace(/\s+/g, ' ').trim();
35	const endsSentence = (text: string) => /[.!?]$/.test(text);
36	
37	/** `cut`, ending on a whole word where there is one to end on. */
38	function cutAtWord(text: string, max: number): string {
39	  if (text.length <= max) return text;
40	  const head = text.slice(0, max - 1);
41	  const space = head.lastIndexOf(' ');
42	  return `${(space > max / 2 ? head.slice(0, space) : head).trimEnd()}…`;
43	}
44	
45	/** The last `max` characters, starting on a line where one starts early enough: a run's summary is at its end. */
46	function tail(text: string, max: number): string {
47	  const trimmed = text.trimEnd();
48	  if (trimmed.length <= max) return trimmed;
49	  const end = trimmed.slice(trimmed.length - (max - 1));
50	  const lineStart = end.indexOf('\n') + 1;
51	  return `…${lineStart > 0 && lineStart < end.length / 2 ? end.slice(lineStart) : end}`;
52	}
53	
54	function day(iso: string): string {
55	  const ms = Date.parse(iso);
56	  return Number.isNaN(ms) ? cut(flat(iso), 24) : new Date(ms).toISOString().slice(0, 10);
57	}
58	
59	function realityOf(claim: FlaggedClaim): string {
60	  if (claim.verdict === 'stale') return 'Code was edited after the last passing run.';
61	  if (claim.kind === 'tests_pass') return 'The last test run before that message had failed.';
62	  const reason = flat(claim.reason ?? '') || 'the record contradicts this claim';
63	  return cut(`${reason[0]!.toUpperCase()}${reason.slice(1)}${endsSentence(reason) ? '' : '.'}`, ON_SCREEN.flagReality);
64	}
65	
66	/**
67	 * The flag scene for a claim a rule found contradicted or stale. Every word of it is the agent's own quote,
68	 * a fixed sentence, or the rule's reason: no model writes any part of a flag.
69	 */
70	export function flagScene(claim: FlaggedClaim): SceneOf<'flag'> {
71	  const quote = flat(claim.quote);
72	  const spoken = cutAtWord(quote, SPOKEN_QUOTE_CHARS);
73	  const reality = realityOf(claim);
74	  return {
75	    id: `flag_${claim.id}`,
76	    type: 'flag',
77	    claimId: claim.id,
78	    verdict: claim.verdict,
79	    quote: cut(quote, ON_SCREEN.flagQuote),
80	    reality,
81	    lines: [
82	      // What the agent wrote rests on the entry that holds the words; what the record shows rests on what the rule found.
83	      { id: `flag_${claim.id}_quote`, text: `The agent wrote: "${spoken}"${endsSentence(spoken) ? '' : '.'}`, evidence: [{ type: 'entry', entryId: claim.entryId, quote: claim.quote }] },
84	      { id: `flag_${claim.id}_reality`, text: reality, evidence: claim.evidence },
85	    ],
86	  };
87	}
88	
89	const isFlagged = (claim: Claim): claim is FlaggedClaim => (claim.verdict === 'contradicted' || claim.verdict === 'stale') && claim.evidence.length > 0;
90	
91	// The writer points and narrates; it supplies none of what a scene shows. Keys other than these are ignored.
92	const WriterReply = z.object({ scenes: z.array(z.unknown()) });
93	const WriterLine = z.object({ text: z.string().trim().min(1).max(220), evidence: z.array(EvidenceRef).min(1) });
94	const rawLines = z.array(z.unknown());
95	const WriterScene = z.discriminatedUnion('type', [
96	  z.object({ type: z.literal('prompt'), entryId: z.string(), lines: rawLines }),
97	  z.object({ type: z.literal('terminal'), steps: z.array(z.object({ entryId: z.string() })).min(1), lines: rawLines }),
98	  z.object({ type: z.literal('diff'), sha: z.string(), path: z.string(), lines: rawLines }),
99	  z.object({ type: z.literal('stats'), lines: rawLines }),
100	]);
101	type WriterScene = z.infer<typeof WriterScene>;
102	
103	function typeName(raw: unknown): string {
104	  const type = typeof raw === 'object' && raw !== null && 'type' in raw ? raw.type : undefined;
105	  return typeof type === 'string' ? cut(flat(type), 20) : 'untyped';
106	}
107	
108	export function scriptStage(deps: StageDeps): Stage<ScriptArtifact> {
109	  return {
110	    name: 'script',
111	    maxAttempts: 3,
112	    async run(ctx) {
113	      const ingest = ctx.read<IngestArtifact>('ingest');
114	      const { beats } = ctx.read<EditArtifact>('edit');
115	      const verify = ctx.read<VerifyArtifact>('verify');
116	
117	      const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
118	      const entries = new Map(ingest.sessions.flatMap((s) => s.entries.map((e) => [e.id, e] as const)));
119	      const commits = knownCommits(ingest);
120	      const facts = computeFacts(ingest.sessions);
121	      const repo = repoLabel(ctx.run.repoUrl);
122	      const windowLabel = [...new Set([day(ctx.run.since), day(ctx.run.until)])].join(' – ');
123	
124	      const runs = new Map<string, ToolRun[]>();
125	      const runsOf = (session: Session): ToolRun[] => {
126	        if (!runs.has(session.id)) runs.set(session.id, collectRuns(session));
127	        return runs.get(session.id)!;
128	      };
129	
130	      // Newest first: the later session, then the later entry.
131	      const startOf = (claim: Claim) => Date.parse(sessions.get(claim.sessionId)?.startedAt ?? '') || 0;
132	      const indexOf = (claim: Claim) => entries.get(claim.entryId)?.index ?? -1;
133	      const flagged = verify.claims
134	        .filter(isFlagged)
135	        .sort((a, b) => startOf(b) - startOf(a) || indexOf(b) - indexOf(a))
136	        .slice(0, MAX_FLAGS);
137	
138	      /** A shell call the record holds a readable result for, as a terminal step; null when there is nothing to show. */
139	      const stepFor = (entryId: string): Step | null => {
140	        const entry = entries.get(entryId);
141	        const session = entry && sessions.get(entry.sessionId);
142	        if (!entry || !session || entry.toolUseId === undefined) return null;
143	        const call = entry.kind === 'tool_call' ? entry : session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === entry.toolUseId);
144	        if (!call || call.command === undefined) return null;
145	        const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
146	        if (!result) return null;
147	        // A test, build, type-check or lint run gets its mark from the parsed output. One the parser cannot read gets no mark at all.
148	        const run = runsOf(session).find((r) => r.callEntryId === call.id);
149	        if (run?.outcome === 'unknown') return null;
150	        const ok = run ? run.outcome === 'pass' : !(result.isError ?? false);
151	        return { command: cut(flat(call.command), ON_SCREEN.command), output: tail(result.text, ON_SCREEN.output), ok, entryId: call.id };
152	      };
153	
154	      /** The scene the writer pointed at, filled from the record; or the reason there is nothing there to show. */
155	      const frame = (scene: WriterScene, id: string, lines: Line[]): Scene | string => {
156	        if (scene.type === 'prompt') {
