34	index 3333333..4444444 100644
35	--- a/src/status.ts
36	+++ b/src/status.ts
37	@@ -10,3 +10,4 @@ export function status(opts: Options) {
38	   const report = collect();
39	+  if (opts.json) return console.log(JSON.stringify(report));
40	   print(report);
