56	export function session(id: string, entries: PartialEntry[], o: Partial<Session> = {}): Session {
57	  return {
58	    id,
59	    checkpointIds: [`cp_${id}`],
60	    agent: 'claude-code',
61	    model: 'claude-sonnet-4.6',
62	    branch: 'main',
63	    startedAt: '2026-10-10T07:00:00Z',
64	    endedAt: '2026-10-10T07:30:00Z',
65	    turnCount: entries.filter((e) => e.kind === 'user').length,
66	    tokens: { input: 1000, output: 400, cacheRead: 0, cacheWrite: 0 },
67	    commits: [],
68	    filesTouched: [],
69	    ...o,
70	    entries: entries.map((e, index) => ({ ts: null, text: '', ...e, id: `${id}:${index}`, sessionId: id, index })),
71	  };
72	}
73	
74	/**
75	 * Two sessions. In s1 the agent says the tests pass straight after a failing run; s2 is honest:
76	 * it runs the tests, they pass, it says so, and a second turn runs the build.
77	 */
78	export function twoSessions(): IngestArtifact {
79	  const s1 = session(
80	    's1',
81	    [
82	      { kind: 'user', text: 'The queue drops jobs when the worker restarts. Add a retry with backoff.' },
83	      { kind: 'assistant', text: 'I will add a retry loop to the run method.' },
84	      { kind: 'tool_call', toolName: 'Edit', toolUseId: 't1', filePath: 'src/queue.ts', text: '{"file_path":"src/queue.ts"}' },
85	      { kind: 'tool_result', toolUseId: 't1', text: 'ok' },
86	      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't2', command: 'pnpm vitest run test/queue.test.ts', text: '{"command":"pnpm vitest run test/queue.test.ts"}' },
87	      { kind: 'tool_result', toolUseId: 't2', text: FAILED_RUN, isError: true },
88	      { kind: 'assistant', text: 'The retry is in place in `src/queue.ts`. All tests pass and the build is green.' },
89	    ],
90	    { commits: [SHA_A], filesTouched: ['src/queue.ts'] },
91	  );
92	  const s2 = session(
93	    's2',
94	    [
95	      { kind: 'user', text: 'Add a --json flag to the status command.' },
96	      { kind: 'assistant', text: 'I will add the flag and run the tests.' },
97	      { kind: 'tool_call', toolName: 'Edit', toolUseId: 't1', filePath: 'src/status.ts', text: '{"file_path":"src/status.ts"}' },
98	      { kind: 'tool_result', toolUseId: 't1', text: 'ok' },
99	      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't2', command: 'pnpm vitest run test/status.test.ts', text: '{"command":"pnpm vitest run test/status.test.ts"}' },
100	      { kind: 'tool_result', toolUseId: 't2', text: PASSED_RUN },
101	      { kind: 'assistant', text: 'Added the --json flag to the status command. All 3 tests pass.' },
102	      { kind: 'user', text: 'Thanks. Does the build still work?' },
103	      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't3', command: 'pnpm build', text: '{"command":"pnpm build"}' },
104	      { kind: 'tool_result', toolUseId: 't3', text: 'Done in 2.1s' },
105	      { kind: 'assistant', text: 'The build passes.' },
106	    ],
107	    { commits: [SHA_B], filesTouched: ['src/status.ts'], startedAt: '2026-10-10T09:00:00Z', endedAt: '2026-10-10T09:20:00Z' },
108	  );
109	  return {
110	    repo: { url: 'https://github.com/acme/retry-queue', dir: '/tmp/acme__retry-queue', headSha: SHA_B },
111	    sessions: [s1, s2],
112	    diffs: { [`${SHA_A}:src/queue.ts`]: QUEUE_PATCH, [`${SHA_B}:src/status.ts`]: STATUS_PATCH },
113	    skipped: [],
114	    enrichments: {},
115	    redactions: 0,
116	  };
117	}
118	
119	/** One beat per session of `twoSessions`. */
120	export function twoBeats(): { beats: Beat[] } {
121	  return {
122	    beats: [
123	      { id: 'beat_1', kind: 'fix', title: 'Retry for failed jobs', summary: 'The agent added a retry loop to the queue and ran the queue tests.', sessionIds: ['s1'], entryRanges: [{ sessionId: 's1', from: 0, to: 6 }], commits: [SHA_A] },
124	      { id: 'beat_2', kind: 'feature', title: 'JSON output for status', summary: 'The agent added a --json flag to the status command.', sessionIds: ['s2'], entryRanges: [{ sessionId: 's2', from: 0, to: 10 }], commits: [SHA_B] },
125	    ],
126	  };
127	}
128	
129	export const LIE: Claim = {
130	  id: 'c_1',
131	  sessionId: 's1',
132	  entryId: 's1:6',
133	  quote: 'All tests pass and the build is green.',
134	  kind: 'tests_pass',
135	  verdict: 'contradicted',
136	  reason: 'the last recorded run failed',
137	  evidence: [{ type: 'entry', entryId: 's1:4' }, { type: 'entry', entryId: 's1:5' }],
138	};
139	
140	/** What the verify stage finds in `twoSessions`: the lie in s1, two verified claims in s2. */
141	export function threeClaims(): { claims: Claim[]; counts: Record<'verified' | 'contradicted' | 'stale' | 'unverifiable', number> } {
142	  return {
143	    claims: [
144	      LIE,
145	      { id: 'c_2', sessionId: 's2', entryId: 's2:6', quote: 'All 3 tests pass.', kind: 'tests_pass', verdict: 'verified', reason: 'the last recorded run passed with no edits after', evidence: [{ type: 'entry', entryId: 's2:4' }, { type: 'entry', entryId: 's2:5' }] },
146	      { id: 'c_3', sessionId: 's2', entryId: 's2:6', quote: 'Added the --json flag to the status command.', kind: 'implemented', subject: '--json flag', verdict: 'verified', reason: 'the diff contains the quoted change', evidence: [{ type: 'diff', sha: SHA_B, path: 'src/status.ts', quote: 'if (opts.json) return console.log(JSON.stringify(report));' }] },
147	    ],
148	    counts: { verified: 2, contradicted: 1, stale: 0, unverifiable: 0 },
149	  };
150	}
151	
152	const entryRef = (entryId: string) => ({ type: 'entry' as const, entryId });
153	
154	/** A writer reply that follows the arc over `twoSessions`: every pointer and every citation resolves. */
155	export function writerReply() {
156	  return {
157	    scenes: [
158	      { type: 'prompt', entryId: 's1:0', lines: [{ text: 'The session opened with a request to retry failed jobs.', evidence: [entryRef('s1:0')] }] },
159	      { type: 'diff', sha: SHA_A, path: 'src/queue.ts', lines: [{ text: 'The retry lives in the run method of the queue.', evidence: [{ type: 'diff', sha: SHA_A, path: 'src/queue.ts', quote: 'return this.run(job);' }] }] },
160	      { type: 'terminal', steps: [{ entryId: 's1:4' }], lines: [{ text: 'The queue test run failed on the retry count.', evidence: [entryRef('s1:5')] }] },
161	      { type: 'terminal', steps: [{ entryId: 's2:4' }, { entryId: 's2:8' }], lines: [{ text: 'In the second session all 3 tests passed.', evidence: [entryRef('s2:5')] }] },
162	      { type: 'stats', lines: [{ text: 'The window holds 2 sessions and 2 commits.', evidence: [{ type: 'stat', key: 'sessions.count' }, { type: 'stat', key: 'commits.count' }] }] },
163	    ],
164	  };
165	}
166	
167	export const json = (value: unknown): ChatMessage => ({ role: 'assistant', content: JSON.stringify(value) });
168	
169	/** The text of the system and user messages of a request, joined: what the model was told. */
170	export function promptText(messages: ChatMessage[]): string {
171	  return messages
172	    .filter((m) => m.role === 'system' || m.role === 'user')
173	    .map((m) => (typeof m.content === 'string' ? m.content : ''))
174	    .join('\n');
175	}
176	
177	export type MockRequest = { role: Role; messages: ChatMessage[] };
178	
179	const dirs: string[] = [];
180	
181	/** Removes every data directory a harness created. Call from `afterEach`. */
182	export function cleanup(): void {
183	  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
184	}
185	
186	/**
187	 * A run in an in-memory database, stage deps around a scripted model, and a stage context whose `read`
188	 * serves `artifacts` the way the store does: as parsed JSON, throwing when the stage has none.
189	 * Every model call adds `costPerCall` to the meter, as the router does with real spend.
190	 */
191	export function harness(o: {
192	  reply?: (req: MockRequest) => ChatMessage;
193	  artifacts?: Partial<Record<StageName, unknown>>;
194	  budget?: Budget;
195	  tts?: TtsProvider | null;
196	  costPerCall?: number;
197	  repoUrl?: string;
198	} = {}) {
199	  const budget = o.budget ?? DEFAULT_BUDGET;
200	  const db: Database = openDb(':memory:');
201	  const dataDir = mkdtempSync(join(tmpdir(), 'dailies-stages-'));
202	  dirs.push(dataDir);
203	  const runId = createRun(db, {
204	    repoUrl: o.repoUrl ?? 'https://github.com/acme/retry-queue',
205	    since: '2026-10-10T00:00:00Z',
206	    until: '2026-10-11T00:00:00Z',
207	    budget,
208	  });
209	
210	  const meter = new CostMeter(budget.maxCostPerReelUsd);
211	  const calls: MockRequest[] = [];
212	  const mock = createMockClient((req) => {
213	    calls.push(req);
214	    if (!o.reply) throw new Error(`unexpected model call for role ${req.role}`);
215	    return o.reply(req);
216	  });
217	  const client: ModelClient = {
218	    async complete(req) {
219	      meter.add(o.costPerCall ?? 0);
220	      return mock.complete(req);
221	    },
222	  };
223	
224	  const artifacts: Partial<Record<StageName, unknown>> = { ...o.artifacts };
225	  const events: string[] = [];
226	  const ctx = (feedback: string | null = null): StageContext => ({
227	    run: getRun(db, runId),
228	    dataDir,
229	    runDir: join(dataDir, 'runs', runId),
230	    read: <T>(stage: StageName): T => {
231	      if (!(stage in artifacts)) throw new Error(`artifact not found for stage ${stage}`);
232	      return JSON.parse(JSON.stringify(artifacts[stage])) as T;
233	    },
234	    log: (message) => events.push(message),
235	    feedback,
236	  });
237	
238	  const deps: StageDeps = { db, client, meter, tts: o.tts ?? null, voice: 'Charon' };
239	  return { db, dataDir, runId, deps, meter, calls, artifacts, events, ctx };
240	}
241	
242	/** The script stage's own artifact for `twoSessions`, so later stages are tested on what it really produces. */
243	export async function scriptArtifact(o: { reply?: unknown; claims?: Claim[]; ingest?: IngestArtifact } = {}): Promise<ScriptArtifact> {
244	  const verify = threeClaims();
245	  const h = harness({
246	    artifacts: { ingest: o.ingest ?? twoSessions(), edit: twoBeats(), verify: o.claims ? { ...verify, claims: o.claims } : verify },
247	    reply: () => json(o.reply ?? writerReply()),
248	  });
249	  return (await scriptStage(h.deps).run(h.ctx())).artifact;
250	}
251	
252	/** The ground stage's own artifact for `twoSessions`, with a judge that finds every line entailed: 7 lines, 1 flag. */
253	export async function groundArtifact(): Promise<GroundArtifact> {
254	  const h = harness({ artifacts: { ingest: twoSessions(), script: await scriptArtifact() }, reply: () => json({ entailed: true }) });
255	  return (await groundStage(h.deps).run(h.ctx())).artifact;
256	}
