  it('a plain typecheck command is trusted on a clean exit', () => {
    const sess = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm typecheck' },
      { kind: 'tool_result', toolUseId: 't1', text: '$ tsc --noEmit', isError: false },
