    expect(headlineFor('test', '\u001b[31m Tests  2 failed\u001b[0m | 14 passed')).toBe('2 failed');
    expect(headlineFor('test', ' Test Files  3 passed (3)\n Tests  14 passed (14)')).toBe('14 passed');
