  const repoDir = await makeRepo({
    layout: 'refs',
    checkpoints: [
      {
        id: 'headless1',
        sessions: [
          {
            sessionId: 's1',
            createdAt: '2026-10-10T07:00:00Z',
            headless: true,
            lines: [
              { type: 'user', ts: '2026-10-10T07:00:00Z', content: [{ id: 'u1', text: 'do a thing' }] },
