              { type: 'user', ts: '2026-10-10T07:00:10Z', content: [{ id: 'u2', text: 'do another thing' }] },
              { type: 'assistant', ts: '2026-10-10T07:00:15Z', content: [{ type: 'text', text: 'done again' }] },
            ],
          },
        ],
      },
    ],
  });

